import json
import re
from typing import Dict, List, Tuple


def _split_arrow(line: str) -> Tuple[str, str]:
    if "->" in line:
        left, right = line.rsplit("->", 1)
        return left.strip(), right.strip()
    return line.strip(), ""


def _split_speaker(line: str) -> Tuple[str, str]:
    if ":" in line:
        speaker, text = line.split(":", 1)
        return speaker.strip(), text.strip()
    return "", line.strip()


def _escape_dot(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    lines = [ln.strip() for ln in text.splitlines()]

    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for line in lines:
        if not line:
            continue
        if line.startswith("[") and line.endswith("]"):
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = line[1:-1].strip()
            current_lines = []
        else:
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    for section_id, content_lines in sections:
        if not content_lines:
            nodes.append({
                "id": section_id,
                "text": "",
                "speaker": "",
                "type": "line",
            })
            continue

        is_choice = all(re.match(r"^\d+\.\s+", ln) for ln in content_lines)

        if is_choice:
            nodes.append({
                "id": section_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            })
            for ln in content_lines:
                left, target = _split_arrow(ln)
                choice_text = re.sub(r"^\d+\.\s*", "", left).strip()
                if target:
                    edges.append({
                        "from": section_id,
                        "to": target,
                        "text": choice_text,
                    })
        else:
            combined = " ".join(content_lines)
            left, target = _split_arrow(combined)
            speaker, text_only = _split_speaker(left)
            nodes.append({
                "id": section_id,
                "text": text_only,
                "speaker": speaker,
                "type": "line",
            })
            if target:
                edges.append({
                    "from": section_id,
                    "to": target,
                    "text": "",
                })

    node_ids = {n["id"] for n in nodes}
    referenced = {e["to"] for e in edges}
    missing = referenced - node_ids

    if missing:
        if missing == {"End"} or missing.issubset({"End"}):
            if "End" not in node_ids:
                nodes.append({
                    "id": "End",
                    "text": "",
                    "speaker": "",
                    "type": "line",
                })
                node_ids.add("End")
                missing = set()
        else:
            raise ValueError(f"Unknown edge targets: {sorted(missing)}")

    if sections:
        start_id = sections[0][0]
        adj: Dict[str, List[str]] = {nid: [] for nid in node_ids}
        for e in edges:
            adj.setdefault(e["from"], []).append(e["to"])

        reachable = set()
        stack = [start_id]
        while stack:
            cur = stack.pop()
            if cur in reachable:
                continue
            reachable.add(cur)
            for nxt in adj.get(cur, []):
                if nxt not in reachable:
                    stack.append(nxt)

        unreachable = node_ids - reachable
        if unreachable:
            raise ValueError(f"Unreachable nodes from {start_id}: {sorted(unreachable)}")

    return {"nodes": nodes, "edges": edges}


def _graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;"]

    for node in graph["nodes"]:
        shape = "box" if node["type"] == "line" else "diamond"
        label = node["id"]
        lines.append(
            f'  "{_escape_dot(node["id"])}" [label="{_escape_dot(label)}", shape={shape}];'
        )

    for edge in graph["edges"]:
        if edge["text"]:
            lines.append(
                f'  "{_escape_dot(edge["from"])}" -> "{_escape_dot(edge["to"])}" '
                f'[label="{_escape_dot(edge["text"])}"];'
            )
        else:
            lines.append(
                f'  "{_escape_dot(edge["from"])}" -> "{_escape_dot(edge["to"])}";'
            )

    lines.append("}")
    return "\n".join(lines)


if __name__ == "__main__":
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        content = f.read()

    graph = parse_script(content)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, ensure_ascii=True, indent=2)

    dot = _graph_to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
